/* ============================================
   LearnForge — Global Styles
   ============================================ */

:root {
  --color-primary: #1a1a2e;
  --color-accent: #4361ee;
  --color-accent-hover: #3a56d4;
  --color-accent-light: #eef1ff;
  --color-coral: #ff6b6b;
  --color-green: #06d6a0;
  --color-lime: #E6FF32;
  --color-dark: #0f0f23;
  --color-text: #2d3436;
  --color-text-light: #636e72;
  --color-bg: #ffffff;
  --color-bg-alt: #f8f9fc;
  --color-border: #e8ecf1;
  --font-heading: 'Plus Jakarta Sans', 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
  --shadow-md: 0 4px 16px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.1);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --max-width: 1200px;
  --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: var(--font-body);
  color: var(--color-text);
  background: var(--color-bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img { max-width: 100%; display: block; }
a { text-decoration: none; color: inherit; }
button { border: none; background: none; cursor: pointer; font-family: inherit; }
ul, ol { list-style: none; }

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.2;
  color: var(--color-dark);
}

h1 { font-size: clamp(2.2rem, 5vw, 3.5rem); letter-spacing: -0.02em; }
h2 { font-size: clamp(1.8rem, 3.5vw, 2.5rem); letter-spacing: -0.01em; }
h3 { font-size: clamp(1.2rem, 2vw, 1.5rem); }
h4 { font-size: 1.125rem; }

p { color: var(--color-text-light); max-width: 680px; }

.section-label {
  display: inline-block;
  font-size: 0.8125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-accent);
  margin-bottom: 12px;
}

.section-title {
  margin-bottom: 16px;
}

.section-subtitle {
  font-size: 1.125rem;
  line-height: 1.7;
  max-width: 640px;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  border-radius: 50px;
  font-weight: 600;
  font-size: 0.9375rem;
  transition: all var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--color-accent);
  color: #fff;
}

.btn-primary:hover {
  background: var(--color-accent-hover);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(67, 97, 238, 0.35);
}

.btn-secondary {
  background: transparent;
  color: var(--color-accent);
  border: 2px solid var(--color-accent);
}

.btn-secondary:hover {
  background: var(--color-accent);
  color: #fff;
}

.btn-dark {
  background: var(--color-dark);
  color: #fff;
}

.btn-dark:hover {
  background: #1a1a3e;
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(15, 15, 35, 0.3);
}

.btn-white {
  background: #fff;
  color: var(--color-dark);
}

.btn-white:hover {
  background: #f0f0f0;
  transform: translateY(-1px);
}

.btn-sm {
  padding: 10px 20px;
  font-size: 0.875rem;
}

.btn-lg {
  padding: 16px 36px;
  font-size: 1rem;
}

/* ============================================
   Navigation
   ============================================ */
.navbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border);
  transition: box-shadow var(--transition);
}

.navbar.scrolled {
  box-shadow: var(--shadow-md);
}

.navbar .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.nav-logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--color-dark);
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-logo .logo-icon {
  width: 32px;
  height: 32px;
  background: var(--color-accent);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 1.125rem;
  font-weight: 800;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-links a {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-text-light);
  transition: color var(--transition);
  position: relative;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--color-accent);
}

.nav-links a.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--color-accent);
  border-radius: 1px;
}

.nav-cta {
  display: flex;
  align-items: center;
  gap: 12px;
}

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 4px;
}

.hamburger span {
  width: 24px;
  height: 2px;
  background: var(--color-dark);
  border-radius: 2px;
  transition: all var(--transition);
}

.mobile-menu {
  display: none;
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  bottom: 0;
  background: #fff;
  padding: 24px;
  z-index: 999;
  flex-direction: column;
  gap: 8px;
  overflow-y: auto;
}

.mobile-menu.open {
  display: flex;
}

.mobile-menu a {
  display: block;
  padding: 14px 16px;
  font-size: 1.0625rem;
  font-weight: 500;
  border-radius: var(--radius-sm);
  color: var(--color-text);
  transition: background var(--transition);
}

.mobile-menu a:hover {
  background: var(--color-bg-alt);
}

.mobile-menu .btn {
  margin-top: 16px;
  text-align: center;
}

/* ============================================
   Hero Section
   ============================================ */
.hero {
  padding: 140px 0 80px;
  background: linear-gradient(135deg, #f8f9fc 0%, #eef1ff 50%, #f0f7ff 100%);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(67, 97, 238, 0.08) 0%, transparent 70%);
  border-radius: 50%;
}

.hero .container {
  position: relative;
  z-index: 1;
}

.hero-content {
  max-width: 720px;
  margin: 0 auto;
  text-align: center;
}

.hero h1 {
  margin-bottom: 20px;
}

.hero .hero-subtitle {
  font-size: 1.1875rem;
  line-height: 1.7;
  color: var(--color-text-light);
  margin: 0 auto 32px;
  max-width: 600px;
}

.hero-actions {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

/* Hero Tabs (Homepage) */
.hero-tabs {
  margin-top: 48px;
}

.hero-tab-nav {
  display: flex;
  justify-content: center;
  gap: 4px;
  background: rgba(255, 255, 255, 0.8);
  border-radius: 50px;
  padding: 4px;
  display: inline-flex;
  margin: 0 auto;
}

.hero-tab-btn {
  padding: 10px 24px;
  border-radius: 50px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text-light);
  transition: all var(--transition);
}

.hero-tab-btn.active {
  background: var(--color-accent);
  color: #fff;
}

.hero-tab-content {
  margin-top: 32px;
}

.hero-tab-panel {
  display: none;
  animation: fadeUp 0.4s ease;
}

.hero-tab-panel.active {
  display: block;
}

.hero-preview {
  background: #fff;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  overflow: hidden;
  border: 1px solid var(--color-border);
  padding: 24px;
  min-height: 300px;
}

.preview-topbar {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 20px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--color-border);
}

.preview-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #e8ecf1;
}

.preview-dot:nth-child(1) { background: #ff6b6b; }
.preview-dot:nth-child(2) { background: #feca57; }
.preview-dot:nth-child(3) { background: #06d6a0; }

.preview-url {
  flex: 1;
  background: var(--color-bg-alt);
  border-radius: 6px;
  padding: 6px 12px;
  font-size: 0.75rem;
  color: var(--color-text-light);
  margin-left: 8px;
}

.preview-grid {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 20px;
}

.preview-sidebar {
  background: var(--color-bg-alt);
  border-radius: var(--radius-sm);
  padding: 16px;
}

.preview-sidebar-item {
  padding: 8px 12px;
  border-radius: 6px;
  font-size: 0.8125rem;
  color: var(--color-text-light);
  margin-bottom: 4px;
  cursor: default;
}

.preview-sidebar-item.active {
  background: var(--color-accent-light);
  color: var(--color-accent);
  font-weight: 600;
}

.preview-main {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.preview-card {
  background: var(--color-bg-alt);
  border-radius: var(--radius-sm);
  padding: 16px;
}

.preview-card-title {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--color-dark);
  margin-bottom: 8px;
}

.preview-bar {
  height: 8px;
  background: var(--color-border);
  border-radius: 4px;
  margin-bottom: 6px;
}

.preview-bar.filled { background: var(--color-accent); width: 70%; }
.preview-bar.half { width: 45%; }
.preview-bar.short { width: 30%; }

/* Student Preview */
.student-preview-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.student-course-card {
  background: var(--color-bg-alt);
  border-radius: var(--radius-sm);
  overflow: hidden;
}

.student-course-thumb {
  height: 80px;
  background: linear-gradient(135deg, var(--color-accent), #6c63ff);
}

.student-course-thumb:nth-child(1) { background: linear-gradient(135deg, #ff6b6b, #ee5a24); }

.student-course-info {
  padding: 12px;
}

.student-course-info h5 {
  font-size: 0.75rem;
  margin-bottom: 6px;
}

.progress-bar-bg {
  height: 4px;
  background: var(--color-border);
  border-radius: 2px;
}

.progress-bar-fill {
  height: 100%;
  background: var(--color-green);
  border-radius: 2px;
}

/* ============================================
   Stats Bar
   ============================================ */
.stats-bar {
  padding: 48px 0;
  background: var(--color-dark);
  color: #fff;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  text-align: center;
}

.stat-item h3 {
  font-size: clamp(2rem, 4vw, 3rem);
  color: #fff;
  margin-bottom: 4px;
}

.stat-item .stat-accent {
  color: var(--color-lime);
}

.stat-item p {
  color: rgba(255, 255, 255, 0.7);
  font-size: 0.9375rem;
  margin: 0 auto;
}

/* ============================================
   Product Cards
   ============================================ */
.products-section {
  padding: 100px 0;
}

.products-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.product-card {
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 36px;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}

.product-card:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.product-card-icon {
  width: 56px;
  height: 56px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 20px;
}

.product-card-icon.courses { background: #eef1ff; color: var(--color-accent); }
.product-card-icon.coaching { background: #fff0f0; color: var(--color-coral); }
.product-card-icon.downloads { background: #e8fff5; color: var(--color-green); }
.product-card-icon.memberships { background: #fff8e6; color: #f0a500; }

.product-card h3 { margin-bottom: 12px; }
.product-card p { font-size: 0.9375rem; line-height: 1.6; }

.product-card-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 20px;
  font-weight: 600;
  font-size: 0.9375rem;
  color: var(--color-accent);
  transition: gap var(--transition);
}

.product-card-link:hover { gap: 10px; }

/* ============================================
   Why Choose Us (Tabs)
   ============================================ */
.why-choose {
  padding: 100px 0;
  background: var(--color-bg-alt);
}

.why-choose-header {
  text-align: center;
  margin-bottom: 48px;
}

.why-tabs-nav {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: center;
  margin-bottom: 40px;
}

.why-tab-btn {
  padding: 12px 24px;
  border-radius: 50px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text-light);
  background: #fff;
  border: 1px solid var(--color-border);
  transition: all var(--transition);
}

.why-tab-btn.active {
  background: var(--color-accent);
  color: #fff;
  border-color: var(--color-accent);
}

.why-tab-btn:hover:not(.active) {
  border-color: var(--color-accent);
  color: var(--color-accent);
}

.why-tab-panel {
  display: none;
  animation: fadeUp 0.4s ease;
}

.why-tab-panel.active {
  display: block;
}

.why-features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 20px;
}

.why-feature-card {
  background: #fff;
  padding: 28px;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  transition: all var(--transition);
}

.why-feature-card:hover {
  box-shadow: var(--shadow-sm);
  transform: translateY(-2px);
}

.why-feature-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  background: var(--color-accent-light);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
  color: var(--color-accent);
  font-size: 1.125rem;
}

.why-feature-card h4 { margin-bottom: 8px; }
.why-feature-card p { font-size: 0.875rem; }

/* ============================================
   Global Scale / AI Section
   ============================================ */
.global-scale, .ai-section {
  padding: 100px 0;
}

.split-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.split-layout.reverse {
  direction: rtl;
}

.split-layout.reverse > * {
  direction: ltr;
}

.split-visual {
  background: linear-gradient(135deg, var(--color-accent-light), #f0f7ff);
  border-radius: var(--radius-xl);
  padding: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 360px;
  position: relative;
  overflow: hidden;
}

.globe-graphic {
  width: 200px;
  height: 200px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--color-accent), #6c63ff);
  opacity: 0.15;
  position: relative;
}

.globe-graphic::after {
  content: '180+';
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--color-accent);
  opacity: 1;
}

.split-text h2 { margin-bottom: 16px; }
.split-text p { margin-bottom: 24px; }

.feature-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.feature-list-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  font-size: 0.9375rem;
  color: var(--color-text);
}

.feature-list-item .check {
  flex-shrink: 0;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--color-accent-light);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-accent);
  font-size: 0.75rem;
  font-weight: 700;
  margin-top: 1px;
}

/* ============================================
   Testimonials
   ============================================ */
.testimonials {
  padding: 100px 0;
  background: var(--color-bg-alt);
  overflow: hidden;
}

.testimonials-header {
  text-align: center;
  margin-bottom: 48px;
}

.carousel-wrapper {
  position: relative;
  max-width: 100%;
}

.carousel-track {
  display: flex;
  gap: 24px;
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
  will-change: transform;
}

.testimonial-card {
  min-width: 360px;
  background: #fff;
  border-radius: var(--radius-lg);
  padding: 32px;
  border: 1px solid var(--color-border);
  flex-shrink: 0;
}

.testimonial-badge {
  display: inline-block;
  padding: 4px 12px;
  background: var(--color-accent-light);
  color: var(--color-accent);
  border-radius: 50px;
  font-size: 0.75rem;
  font-weight: 600;
  margin-bottom: 16px;
}

.testimonial-card blockquote {
  font-size: 0.9375rem;
  line-height: 1.7;
  color: var(--color-text);
  margin-bottom: 20px;
  font-style: italic;
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 12px;
}

.testimonial-avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--color-accent), #6c63ff);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-weight: 700;
  font-size: 0.875rem;
}

.testimonial-name {
  font-weight: 600;
  font-size: 0.9375rem;
  color: var(--color-dark);
}

.testimonial-role {
  font-size: 0.8125rem;
  color: var(--color-text-light);
}

.carousel-controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-top: 32px;
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: #fff;
  border: 1px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
  color: var(--color-text);
  font-size: 1.125rem;
}

.carousel-btn:hover {
  background: var(--color-accent);
  color: #fff;
  border-color: var(--color-accent);
}

/* ============================================
   Pricing Overview
   ============================================ */
.pricing-section {
  padding: 100px 0;
}

.pricing-header {
  text-align: center;
  margin-bottom: 48px;
}

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 24px;
  max-width: 960px;
  margin: 0 auto;
}

.pricing-card {
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 36px;
  text-align: center;
  transition: all var(--transition);
  position: relative;
}

.pricing-card.featured {
  border-color: var(--color-accent);
  box-shadow: 0 8px 40px rgba(67, 97, 238, 0.15);
  transform: scale(1.02);
}

.pricing-card.featured::before {
  content: 'Most Popular';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--color-accent);
  color: #fff;
  padding: 4px 16px;
  border-radius: 50px;
  font-size: 0.75rem;
  font-weight: 600;
}

.pricing-card h3 { margin-bottom: 8px; }

.pricing-amount {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--color-dark);
  margin: 16px 0 4px;
}

.pricing-amount span {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-text-light);
}

.pricing-desc {
  font-size: 0.875rem;
  color: var(--color-text-light);
  margin-bottom: 24px;
}

.pricing-features {
  text-align: left;
  margin-bottom: 28px;
}

.pricing-features li {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 0;
  font-size: 0.875rem;
  color: var(--color-text);
}

.pricing-features li::before {
  content: '✓';
