  gap: 6px;
  margin-top: 16px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-accent);
}

/* ============================================
   Membership Features
   ============================================ */
.membership-features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
