  text-align: center;
}

.hero h1 {
  margin-bottom: 20px;
}

.hero .hero-subtitle {
  font-size: 1.1875rem;
  line-height: 1.7;
  color: var(--color-text-light);
  margin: 0 auto 32px;
  max-width: 600px;
}

.hero-actions {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

/* Hero Tabs (Homepage) */
.hero-tabs {
  margin-top: 48px;
}

.hero-tab-nav {
  display: flex;
  justify-content: center;
  gap: 4px;
  background: rgba(255, 255, 255, 0.8);
  border-radius: 50px;
  padding: 4px;
  display: inline-flex;
  margin: 0 auto;
}

.hero-tab-btn {
  padding: 10px 24px;
  border-radius: 50px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text-light);
  transition: all var(--transition);
}

.hero-tab-btn.active {
  background: var(--color-accent);
  color: #fff;
}

.hero-tab-content {
  margin-top: 32px;
}

.hero-tab-panel {
  display: none;
  animation: fadeUp 0.4s ease;
}

.hero-tab-panel.active {
  display: block;
}

.hero-preview {
  background: #fff;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  overflow: hidden;
  border: 1px solid var(--color-border);
  padding: 24px;
  min-height: 300px;
}

.preview-topbar {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 20px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--color-border);
}

.preview-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #e8ecf1;
}

.preview-dot:nth-child(1) { background: #ff6b6b; }
.preview-dot:nth-child(2) { background: #feca57; }
.preview-dot:nth-child(3) { background: #06d6a0; }

.preview-url {
  flex: 1;
  background: var(--color-bg-alt);
  border-radius: 6px;
  padding: 6px 12px;
  font-size: 0.75rem;
  color: var(--color-text-light);
  margin-left: 8px;
}

.preview-grid {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 20px;
}

.preview-sidebar {
  background: var(--color-bg-alt);
  border-radius: var(--radius-sm);
  padding: 16px;
}

.preview-sidebar-item {
  padding: 8px 12px;
  border-radius: 6px;
  font-size: 0.8125rem;
  color: var(--color-text-light);
  margin-bottom: 4px;
  cursor: default;
}

.preview-sidebar-item.active {
  background: var(--color-accent-light);
  color: var(--color-accent);
  font-weight: 600;
}

.preview-main {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.preview-card {
  background: var(--color-bg-alt);
  border-radius: var(--radius-sm);
  padding: 16px;
}

.preview-card-title {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--color-dark);
  margin-bottom: 8px;
}

.preview-bar {
  height: 8px;
  background: var(--color-border);
  border-radius: 4px;
  margin-bottom: 6px;
}

.preview-bar.filled { background: var(--color-accent); width: 70%; }
.preview-bar.half { width: 45%; }
.preview-bar.short { width: 30%; }

/* Student Preview */
.student-preview-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.student-course-card {
  background: var(--color-bg-alt);
  border-radius: var(--radius-sm);
  overflow: hidden;
}

.student-course-thumb {
  height: 80px;
  background: linear-gradient(135deg, var(--color-accent), #6c63ff);
}

.student-course-thumb:nth-child(1) { background: linear-gradient(135deg, #ff6b6b, #ee5a24); }

.student-course-info {
  padding: 12px;
}

.student-course-info h5 {
  font-size: 0.75rem;
  margin-bottom: 6px;
}

.progress-bar-bg {
  height: 4px;
  background: var(--color-border);
  border-radius: 2px;
}

.progress-bar-fill {
  height: 100%;
  background: var(--color-green);
  border-radius: 2px;
}

/* ============================================
   Stats Bar
   ============================================ */
.stats-bar {
  padding: 48px 0;
  background: var(--color-dark);
  color: #fff;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  text-align: center;
}

.stat-item h3 {
  font-size: clamp(2rem, 4vw, 3rem);
  color: #fff;
  margin-bottom: 4px;
}

.stat-item .stat-accent {
  color: var(--color-lime);
}

.stat-item p {
  color: rgba(255, 255, 255, 0.7);
  font-size: 0.9375rem;
  margin: 0 auto;
}

/* ============================================
   Product Cards
   ============================================ */
.products-section {
  padding: 100px 0;
}

.products-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.product-card {
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 36px;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}

.product-card:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.product-card-icon {
  width: 56px;
  height: 56px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 20px;
}

.product-card-icon.courses { background: #eef1ff; color: var(--color-accent); }
.product-card-icon.coaching { background: #fff0f0; color: var(--color-coral); }
.product-card-icon.downloads { background: #e8fff5; color: var(--color-green); }
.product-card-icon.memberships { background: #fff8e6; color: #f0a500; }

.product-card h3 { margin-bottom: 12px; }
.product-card p { font-size: 0.9375rem; line-height: 1.6; }

.product-card-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 20px;
  font-weight: 600;
  font-size: 0.9375rem;
  color: var(--color-accent);
  transition: gap var(--transition);
}

.product-card-link:hover { gap: 10px; }

/* ============================================
   Why Choose Us (Tabs)
   ============================================ */
.why-choose {
  padding: 100px 0;
  background: var(--color-bg-alt);
}

.why-choose-header {
  text-align: center;
  margin-bottom: 48px;
}

.why-tabs-nav {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: center;
  margin-bottom: 40px;
}

.why-tab-btn {
  padding: 12px 24px;
  border-radius: 50px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text-light);
  background: #fff;
  border: 1px solid var(--color-border);
  transition: all var(--transition);
}

.why-tab-btn.active {
  background: var(--color-accent);
  color: #fff;
  border-color: var(--color-accent);
}

.why-tab-btn:hover:not(.active) {
  border-color: var(--color-accent);
  color: var(--color-accent);
}

.why-tab-panel {
  display: none;
  animation: fadeUp 0.4s ease;
}

.why-tab-panel.active {
  display: block;
}

.why-features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 20px;
}

.why-feature-card {
  background: #fff;
  padding: 28px;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  transition: all var(--transition);
}

.why-feature-card:hover {
  box-shadow: var(--shadow-sm);
  transform: translateY(-2px);
}

.why-feature-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  background: var(--color-accent-light);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
  color: var(--color-accent);
  font-size: 1.125rem;
}

.why-feature-card h4 { margin-bottom: 8px; }
.why-feature-card p { font-size: 0.875rem; }

/* ============================================
   Global Scale / AI Section
   ============================================ */
.global-scale, .ai-section {
  padding: 100px 0;
}

.split-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.split-layout.reverse {
  direction: rtl;
}

.split-layout.reverse > * {
  direction: ltr;
}

.split-visual {
  background: linear-gradient(135deg, var(--color-accent-light), #f0f7ff);
  border-radius: var(--radius-xl);
  padding: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 360px;
  position: relative;
  overflow: hidden;
}

.globe-graphic {
  width: 200px;
  height: 200px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--color-accent), #6c63ff);
  opacity: 0.15;
  position: relative;
}

.globe-graphic::after {
  content: '180+';
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--color-accent);
  opacity: 1;
}

.split-text h2 { margin-bottom: 16px; }
.split-text p { margin-bottom: 24px; }

.feature-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.feature-list-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  font-size: 0.9375rem;
  color: var(--color-text);
}

.feature-list-item .check {
  flex-shrink: 0;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--color-accent-light);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-accent);
  font-size: 0.75rem;
  font-weight: 700;
  margin-top: 1px;
}

/* ============================================
   Testimonials
   ============================================ */
.testimonials {
  padding: 100px 0;
  background: var(--color-bg-alt);
  overflow: hidden;
}

.testimonials-header {
  text-align: center;
  margin-bottom: 48px;
}

.carousel-wrapper {
  position: relative;
  max-width: 100%;
}

.carousel-track {
  display: flex;
  gap: 24px;
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
  will-change: transform;
}

.testimonial-card {
  min-width: 360px;
  background: #fff;
  border-radius: var(--radius-lg);
  padding: 32px;
  border: 1px solid var(--color-border);
  flex-shrink: 0;
}

.testimonial-badge {
  display: inline-block;
  padding: 4px 12px;
  background: var(--color-accent-light);
  color: var(--color-accent);
  border-radius: 50px;
  font-size: 0.75rem;
  font-weight: 600;
  margin-bottom: 16px;
}

.testimonial-card blockquote {
  font-size: 0.9375rem;
  line-height: 1.7;
  color: var(--color-text);
  margin-bottom: 20px;
  font-style: italic;
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 12px;
}

.testimonial-avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--color-accent), #6c63ff);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-weight: 700;
  font-size: 0.875rem;
}

.testimonial-name {
  font-weight: 600;
  font-size: 0.9375rem;
  color: var(--color-dark);
}

.testimonial-role {
  font-size: 0.8125rem;
  color: var(--color-text-light);
}

.carousel-controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-top: 32px;
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: #fff;
  border: 1px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
  color: var(--color-text);
  font-size: 1.125rem;
}

.carousel-btn:hover {
  background: var(--color-accent);
  color: #fff;
  border-color: var(--color-accent);
}

/* ============================================
   Pricing Overview
   ============================================ */
.pricing-section {
  padding: 100px 0;
}

.pricing-header {
  text-align: center;
  margin-bottom: 48px;
}

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 24px;
  max-width: 960px;
  margin: 0 auto;
}

.pricing-card {
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 36px;
  text-align: center;
  transition: all var(--transition);
  position: relative;
}

.pricing-card.featured {
  border-color: var(--color-accent);
  box-shadow: 0 8px 40px rgba(67, 97, 238, 0.15);
  transform: scale(1.02);
}

.pricing-card.featured::before {
  content: 'Most Popular';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--color-accent);
  color: #fff;
  padding: 4px 16px;
  border-radius: 50px;
  font-size: 0.75rem;
  font-weight: 600;
}

.pricing-card h3 { margin-bottom: 8px; }

.pricing-amount {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--color-dark);
  margin: 16px 0 4px;
}

.pricing-amount span {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-text-light);
}

.pricing-desc {
  font-size: 0.875rem;
  color: var(--color-text-light);
  margin-bottom: 24px;
}

.pricing-features {
  text-align: left;
  margin-bottom: 28px;
}

.pricing-features li {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 0;
  font-size: 0.875rem;
  color: var(--color-text);
}

.pricing-features li::before {
  content: '✓';
  color: var(--color-green);
  font-weight: 700;
}

.pricing-card .btn { width: 100%; }

.pricing-note {
  text-align: center;
  margin-top: 32px;
  font-size: 0.875rem;
  color: var(--color-text-light);
}

/* ============================================
   Integrations
   ============================================ */
.integrations {
  padding: 100px 0;
  background: var(--color-bg-alt);
}

.integrations-header {
  text-align: center;
  margin-bottom: 48px;
}

.integrations-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 16px;
  max-width: 900px;
  margin: 0 auto;
}

.integration-card {
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 24px 16px;
  text-align: center;
  transition: all var(--transition);
}

.integration-card:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-sm);
  transform: translateY(-2px);
}

.integration-icon {
  width: 48px;
  height: 48px;
  margin: 0 auto 12px;
  border-radius: var(--radius-sm);
  background: var(--color-bg-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-accent);
}

.integration-card span {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--color-text);
}

/* ============================================
   Social Proof
   ============================================ */
.social-proof {
  padding: 80px 0;
  text-align: center;
}

.social-proof h2 { margin-bottom: 16px; }
.social-proof p { margin: 0 auto 32px; }

/* ============================================
   FAQ
   ============================================ */
.faq-section {
  padding: 100px 0;
}

.faq-header {
  text-align: center;
  margin-bottom: 48px;
}

.faq-list {
  max-width: 720px;
  margin: 0 auto;
}

.faq-item {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  margin-bottom: 12px;
  background: #fff;
  overflow: hidden;
  transition: all var(--transition);
}

.faq-item:hover {
  border-color: var(--color-accent);
}

.faq-question {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 20px 24px;
  width: 100%;
  text-align: left;
  font-weight: 600;
  font-size: 0.9375rem;
  color: var(--color-dark);
  cursor: pointer;
  transition: color var(--transition);
}

.faq-question:hover { color: var(--color-accent); }

.faq-icon {
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--color-bg-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
  font-size: 0.875rem;
  color: var(--color-text-light);
}

.faq-item.open .faq-icon {
  background: var(--color-accent);
  color: #fff;
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s cubic-bezier(0.4, 0, 0.2, 1), padding 0.4s ease;
}

.faq-answer-inner {
  padding: 0 24px 20px;
  font-size: 0.9375rem;
  line-height: 1.7;
  color: var(--color-text-light);
}

.faq-item.open .faq-answer {
  max-height: 300px;
}

/* ============================================
   CTA Banner
   ============================================ */
.cta-banner {
  padding: 100px 0;
  background: var(--color-dark);
  text-align: center;
  position: relative;
  overflow: hidden;
}

.cta-banner::before {
  content: '';
  position: absolute;
  top: -50%;
  left: -10%;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, rgba(67, 97, 238, 0.2) 0%, transparent 70%);
  border-radius: 50%;
}

.cta-banner::after {
  content: '';
  position: absolute;
  bottom: -40%;
  right: -10%;
  width: 300px;
  height: 300px;
  background: radial-gradient(circle, rgba(230, 255, 50, 0.1) 0%, transparent 70%);
  border-radius: 50%;
}

.cta-banner .container {
  position: relative;
  z-index: 1;
}

.cta-banner h2 {
  color: #fff;
  margin-bottom: 16px;
}

.cta-banner p {
  color: rgba(255, 255, 255, 0.7);
  margin: 0 auto 32px;
  font-size: 1.125rem;
}

.cta-banner .btn-primary {
  font-size: 1.0625rem;
  padding: 16px 40px;
}

/* ============================================
   Footer
   ============================================ */
.footer {
  background: var(--color-dark);
  color: rgba(255, 255, 255, 0.7);
  padding: 80px 0 32px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: 48px;
  margin-bottom: 48px;
}

.footer-brand {
  max-width: 280px;
}

.footer-brand .nav-logo {
  color: #fff;
  margin-bottom: 16px;
}

.footer-brand p {
  font-size: 0.875rem;
  line-height: 1.7;
  color: rgba(255, 255, 255, 0.5);
}

.footer-col h4 {
  color: #fff;
  font-size: 0.875rem;
  margin-bottom: 20px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.footer-col a {
  display: block;
  padding: 4px 0;
  font-size: 0.875rem;
  color: rgba(255, 255, 255, 0.5);
  transition: color var(--transition);
}

.footer-col a:hover { color: #fff; }

.footer-bottom {
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8125rem;
  color: rgba(255, 255, 255, 0.4);
}

/* ============================================
   Feature Cards (Product pages)
   ============================================ */
.features-section {
  padding: 100px 0;
}

.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.feature-card {
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all var(--transition);
}

.feature-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-3px);
}

.feature-card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: var(--color-accent-light);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  margin-bottom: 20px;
  color: var(--color-accent);
}

.feature-card h3 { margin-bottom: 10px; font-size: 1.25rem; }
.feature-card p { font-size: 0.9375rem; line-height: 1.6; }

/* ============================================
   Tools Grid
   ============================================ */
.tools-section {
  padding: 100px 0;
  background: var(--color-bg-alt);
}

.tools-category {
  margin-bottom: 32px;
}

.tools-category h4 {
  font-size: 0.8125rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-accent);
  margin-bottom: 12px;
}

.tools-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.tool-tag {
  padding: 8px 16px;
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: 50px;
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--color-text);
  transition: all var(--transition);
}

.tool-tag:hover {
  border-color: var(--color-accent);
  color: var(--color-accent);
}

/* ============================================
   File Types Grid
   ============================================ */
.file-types-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 16px;
  margin-top: 40px;
}

.file-type-card {
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 24px;
  text-align: center;
  transition: all var(--transition);
}

.file-type-card:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-sm);
}

.file-type-icon {
  font-size: 2rem;
  margin-bottom: 12px;
}

.file-type-card span {
  font-weight: 600;
  font-size: 0.875rem;
  color: var(--color-dark);
}

/* ============================================
   Steps Section
   ============================================ */
.steps-section {
  padding: 100px 0;
}

.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  margin-top: 48px;
}

.step-card {
  text-align: center;
  padding: 32px;
}

.step-number {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--color-accent);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  font-weight: 800;
  margin: 0 auto 20px;
}

.step-card h3 { margin-bottom: 12px; }
.step-card p { font-size: 0.9375rem; margin: 0 auto; }

/* ============================================
   Spotlight Cards
   ============================================ */
.spotlight-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.spotlight-card {
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--transition);
}

.spotlight-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-3px);
}

.spotlight-image {
  height: 180px;
  background: linear-gradient(135deg, var(--color-accent-light), #f0f7ff);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
}

.spotlight-card:nth-child(2) .spotlight-image {
  background: linear-gradient(135deg, #fff0f0, #ffe8e8);
}

.spotlight-card:nth-child(3) .spotlight-image {
  background: linear-gradient(135deg, #e8fff5, #d0ffe8);
}

.spotlight-body {
  padding: 24px;
}

.spotlight-body h3 { margin-bottom: 8px; font-size: 1.125rem; }
.spotlight-body p { font-size: 0.875rem; }

/* ============================================
   Resources Section
   ============================================ */
.resources-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.resource-card {
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 28px;
  transition: all var(--transition);
}

.resource-card:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-sm);
}

.resource-tag {
  display: inline-block;
  padding: 4px 10px;
  background: var(--color-accent-light);
  color: var(--color-accent);
  border-radius: 50px;
  font-size: 0.6875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 16px;
}

.resource-card h4 { margin-bottom: 8px; }
.resource-card p { font-size: 0.875rem; }

.resource-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 16px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-accent);
}

/* ============================================
   Membership Features
   ============================================ */
.membership-features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  margin-top: 48px;
}

.membership-stat {
  text-align: center;
  padding: 40px 24px;
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
}

.membership-stat .big-number {
  font-size: 3rem;
  font-weight: 800;
  color: var(--color-accent);
  line-height: 1;
  margin-bottom: 12px;
}

.membership-stat h3 { margin-bottom: 10px; font-size: 1.125rem; }
.membership-stat p { font-size: 0.875rem; margin: 0 auto; }

/* ============================================
   Animations
   ============================================ */
@keyframes fadeUp {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: translateY(0); }
}

.fade-in {
  opacity: 0;
  transform: translateY(20px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

.fade-in.visible {
  opacity: 1;
  transform: translateY(0);
}

/* ============================================
   Responsive
   ============================================ */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
  .split-layout { grid-template-columns: 1fr; gap: 40px; }
  .split-layout.reverse { direction: ltr; }
  .preview-grid { grid-template-columns: 1fr; }
  .student-preview-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .nav-links, .nav-cta { display: none; }
  .hamburger { display: flex; }

  .hero { padding: 120px 0 60px; }
  h1 { font-size: 2rem; }

  .stats-grid { grid-template-columns: 1fr; gap: 24px; }
  .products-grid { grid-template-columns: 1fr; }
  .features-grid { grid-template-columns: 1fr; }
  .steps-grid { grid-template-columns: 1fr; }
  .spotlight-grid { grid-template-columns: 1fr; }
  .resources-grid { grid-template-columns: 1fr; }
  .membership-features-grid { grid-template-columns: 1fr; }
  .pricing-cards { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; gap: 12px; text-align: center; }
  .integrations-grid { grid-template-columns: repeat(3, 1fr); }
  .file-types-grid { grid-template-columns: repeat(2, 1fr); }
  .why-tabs-nav { gap: 6px; }
  .why-tab-btn { padding: 10px 16px; font-size: 0.8125rem; }
  .testimonial-card { min-width: 300px; }
  .student-preview-grid { grid-template-columns: 1fr; }
  .hero-tab-nav { flex-direction: column; border-radius: var(--radius-md); }
  .hero-tab-btn { border-radius: var(--radius-sm); }
}

@media (max-width: 480px) {
  .container { padding: 0 16px; }
  .integrations-grid { grid-template-columns: repeat(2, 1fr); }
  .testimonial-card { min-width: 280px; }
}
